# UAUD (Untrapped Auto-Update & Diagnostics) ver 1.0.0 - TRUE BASELINE
# UAUD owns diagnosis/orchestration. UARD owns repair. UARD is deployed before it is launched.
$ErrorActionPreference='SilentlyContinue'
$UAUDName='UAUD (Untrapped Auto-Update & Diagnostics)';$UAUDVersion='1.0.0';$UARDName='UARD (Untrapped Auto-Repair Diagnostic)';$UARDVersion='1.0.0'
$Root=Split-Path -Parent $MyInvocation.MyCommand.Path;$Parent=Split-Path -Parent $Root;$ReportPath=Join-Path $Root 'diagnostic-latest.txt';$RepairPath=Join-Path $Root 'self-repair.ps1';$Repo='https://raw.githubusercontent.com/mehdishah5372-hue/Untrapped/main/'
$lines=New-Object 'System.Collections.Generic.List[string]';$problems=New-Object 'System.Collections.Generic.List[string]';$repairResult='NOT RUN';$updateResult='UNKNOWN';$deployment='NOT NEEDED'
$core=@('config.json','packet-filter.ps1','self-repair.ps1','status-untrapped.ps1','ultra-mode.ps1');$ext=@('manifest.json','background.js','content.js','popup.html','popup.js','bootstrap.bundle.min.js')
function Log([string]$x){$s='['+(Get-Date -Format HH:mm:ss)+'] '+$x;Write-Host $s;[void]$lines.Add($s)}
function Hash([byte[]]$b){$h=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($h.ComputeHash($b))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()}}
function Remote([string]$p){try{$r=Invoke-WebRequest -Uri ($Repo+$p+'?cb='+[DateTime]::UtcNow.Ticks) -UseBasicParsing -TimeoutSec 30 -ErrorAction Stop;[Text.Encoding]::UTF8.GetBytes([string]$r.Content)}catch{$null}}
function ValidScript([byte[]]$b){try{if($b.Length-lt20){return $false};[void][scriptblock]::Create([Text.Encoding]::UTF8.GetString($b));$true}catch{$false}}
function Same([string]$remotePath,[string]$localPath){if(!(Test-Path -LiteralPath $localPath)){return $false};$r=Remote $remotePath;if($null-eq$r){return $null};try{(Hash ([IO.File]::ReadAllBytes($localPath)))-eq(Hash $r)}catch{$false}}
function HTTPS([string]$h){try{(Test-NetConnection $h -Port 443 -WarningAction SilentlyContinue).TcpTestSucceeded}catch{$false}}
function BraveCopies{$o=@();$ud=Join-Path $env:LOCALAPPDATA 'BraveSoftware\Brave-Browser\User Data';if(Test-Path $ud){foreach($p in @(Get-ChildItem $ud -Directory -ErrorAction SilentlyContinue|?{$_.Name-eq'Default'-or$_.Name-like'Profile *'})){foreach($v in @(Get-ChildItem (Join-Path $p.FullName 'Extensions') -Directory -Recurse -ErrorAction SilentlyContinue)){foreach($z in @(Get-ChildItem $v.FullName -Directory -ErrorAction SilentlyContinue)){$m=Join-Path $z.FullName 'manifest.json';if(Test-Path $m){try{if(([string](Get-Content $m -Raw|ConvertFrom-Json).name)-eq'Untrapped'){$o+=$z.FullName}}catch{}}}}}};return @($o|Sort-Object -Unique)}
function Diagnose{
 Log '[POLICY] Checking configuration, schedule and override.';$c=$null;$scheduled=$false;$override=$false;try{$c=Get-Content (Join-Path $Root 'config.json') -Raw|ConvertFrom-Json;$a=[TimeSpan]::Parse($c.start);$b=[TimeSpan]::Parse($c.end);$n=(Get-Date).TimeOfDay;$inside=if($a-lt$b){$n-ge$a-and$n-lt$b}else{$n-ge$a-or$n-lt$b};$o=Join-Path $Root 'override-until.txt';if(Test-Path $o){try{$override=[DateTime]::UtcNow-lt([DateTime]::Parse((Get-Content $o -Raw)).ToUniversalTime()}catch{[void]$problems.Add('Override file is unreadable.')}};$scheduled=[bool]($c.enabled-and$inside-and-not$override);Write-Host ('[STATUS] Policy: '+$(if($c.enabled){'ENABLED'}else{'DISABLED'}));Write-Host ('[STATUS] Schedule: '+$c.start+' - '+$c.end);Write-Host ('[STATUS] Scheduled blocking: '+$(if($scheduled){'ACTIVE'}else{'INACTIVE'}));Write-Host ('[STATUS] Override: '+$(if($override){'ACTIVE'}else{'INACTIVE'}))}catch{[void]$problems.Add('Config is invalid or unreadable.')}
 Log '[POLICY] Checking actual YouTube, ChatGPT and CrushOn reachability.';$yt=HTTPS 'www.youtube.com';$ch=HTTPS 'chatgpt.com';$cr=HTTPS 'www.crushon.ai';$want=-not$scheduled;Write-Host ('[STATUS] YouTube: '+$(if($yt){'REACHABLE'}else{'BLOCKED'}));Write-Host ('[STATUS] ChatGPT: '+$(if($ch){'REACHABLE'}else{'BLOCKED'}));Write-Host ('[STATUS] CrushOn: '+$(if($cr){'REACHABLE'}else{'BLOCKED'}));if($c){if($yt-ne$want){[void]$problems.Add('YouTube does not match configured policy.')};if($ch-ne$want){[void]$problems.Add('ChatGPT does not match configured policy.')};if($cr){[void]$problems.Add('CrushOn is reachable despite always-block policy.')}}
 Log '[CORE] Checking canonical operational source.';$bad=@();$unknown=@();foreach($f in$core){$x=Same ('ultra-mode/'+$f) (Join-Path $Root $f);if($x-eq$false){$bad+=$f}elseif($null-eq$x){$unknown+=$f}};Write-Host ('[STATUS] Core source: '+$(if($bad.Count){'MISMATCH'}elseif($unknown.Count){'UNVERIFIED'}else{'CURRENT'}));if($bad.Count){[void]$problems.Add('Untrapped core differs from canonical GitHub: '+($bad-join ', '))}
 $nativeOK=(Test-Path (Join-Path $Root 'WinDivert.dll'))-and(Test-Path (Join-Path $Root 'WinDivert64.sys'));Write-Host ('[STATUS] WinDivert native files: '+$(if($nativeOK){'PRESENT'}else{'MISSING'}));if(!$nativeOK){[void]$problems.Add('Required WinDivert native component is missing.')}
 $packet=@(Get-CimInstance Win32_Process|?{$_.CommandLine-like'*packet-filter.ps1*'});$control=@(Get-CimInstance Win32_Process|?{$_.CommandLine-like'*ultra-mode.ps1*'});Write-Host ('[STATUS] Packet filter: '+$(if($packet.Count){'RUNNING'}else{'STOPPED'}));Write-Host ('[STATUS] Control plane: '+$(if($control.Count){'RUNNING'}else{'STOPPED'}));if(!$packet.Count){[void]$problems.Add('Packet filter is not running.')};if(!$control.Count){[void]$problems.Add('Control plane is not running.')}
 Log '[EXTENSION] Checking canonical extension source.';$ebad=@();$eunknown=@();foreach($f in$ext){$x=Same $f (Join-Path $Parent $f);if($x-eq$false){$ebad+=$f}elseif($null-eq$x){$eunknown+=$f}};Write-Host ('[STATUS] Extension source: '+$(if($ebad.Count){'MISMATCH'}elseif($eunknown.Count){'UNVERIFIED'}else{'CURRENT'}));if($ebad.Count){[void]$problems.Add('Enhanced extension source differs from canonical GitHub: '+($ebad-join ', '))}
 Log '[BRAVE] Checking installed Untrapped copies.';$bc=BraveCopies;Write-Host ('[STATUS] Brave Untrapped copies: '+$bc.Count+' '+$(if($bc.Count){'FOUND'}else{'NOT FOUND - INFORMATIONAL'}));
 Log '[NETWORK] Checking DNS, HTTPS, Hosts and BFE.';$dns=$false;try{$dns=@(Resolve-DnsName google.com -DnsOnly -ErrorAction Stop|? IPAddress).Count-gt0}catch{};$goo=HTTPS 'www.google.com';$bfe=$false;try{$bfe=(Get-Service BFE).Status-eq'Running'}catch{};$hp=Join-Path $env:SystemRoot 'System32\drivers\etc\hosts';$hosts=@();if(Test-Path $hp){$hosts=@(Get-Content $hp|?{$_-match'(?i)(youtube|youtu\.be|chatgpt|crushon)'-and$_-notmatch'^\s*#'})};Write-Host ('[STATUS] DNS: '+$(if($dns){'OK'}else{'FAILED'}));Write-Host ('[STATUS] Google HTTPS: '+$(if($goo){'OK'}else{'FAILED'}));Write-Host ('[STATUS] Relevant Hosts entries: '+$hosts.Count);Write-Host ('[STATUS] BFE: '+$(if($bfe){'RUNNING'}else{'NOT RUNNING/UNKNOWN'}));if(!$dns){[void]$problems.Add('External DNS resolution is failing.')};if(!$goo){[void]$problems.Add('External HTTPS connectivity to Google is failing.')};if($hosts.Count){[void]$problems.Add('Relevant Hosts entries were found.')};if(!$bfe){[void]$problems.Add('Base Filtering Engine is not running.')}
 return @{Problems=@($problems);CoreBad=$bad;CoreUnknown=$unknown;ExtBad=$ebad;ExtUnknown=$eunknown;Brave=$bc;Packet=$packet;Control=$control;Dns=$dns;Google=$goo;Hosts=$hosts;Bfe=$bfe}}
function DeployUARD{
 Log '[UARD DEPLOY] Checking whether UARD exists and matches the canonical baseline.';if(!(Test-Path $RepairPath)){Log '[UARD DEPLOY] UARD missing: deployment required.';$needs=$true}else{$r=Remote 'ultra-mode/self-repair.ps1';if($null-eq$r){Log '[UARD DEPLOY] GitHub unavailable: deployment cannot be verified.';return 'UNVERIFIED'};$needs=(Hash ([IO.File]::ReadAllBytes($RepairPath)))-ne(Hash $r);if($needs){Log '[UARD DEPLOY] Installed UARD differs from canonical baseline: deployment required.'}else{Log '[UARD DEPLOY] UARD is present and current: deployment not required.'}};if(!$needs){return 'CURRENT'};$r=Remote 'ultra-mode/self-repair.ps1';if($null-eq$r){return 'UNVERIFIED'};if(!(ValidScript $r)){Log '[UARD DEPLOY] Canonical UARD failed PowerShell parser validation.';return 'FAILED'};$bak=$RepairPath+'.pre-deploy-'+(Get-Date -Format yyyyMMdd-HHmmss)+'.bak';try{if(Test-Path $RepairPath){Copy-Item $RepairPath $bak -Force;Log ('[UARD DEPLOY] Backup: '+$bak)};[IO.File]::WriteAllBytes($RepairPath+'.deploy.tmp',$r);if((Hash ([IO.File]::ReadAllBytes($RepairPath+'.deploy.tmp')))-ne(Hash $r)){throw 'Deployment SHA-256 verification failed.'};Move-Item ($RepairPath+'.deploy.tmp') $RepairPath -Force;if((Hash ([IO.File]::ReadAllBytes($RepairPath)))-ne(Hash $r)){throw 'Post-deployment SHA-256 verification failed.'};Log '[UARD DEPLOY] UARD deployed and verified.';return 'DEPLOYED'}catch{Log ('[UARD DEPLOY] FAILED: '+$_.Exception.Message);Remove-Item ($RepairPath+'.deploy.tmp') -Force -ErrorAction SilentlyContinue;return 'FAILED'}}
[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12;Log "=== $UAUDName ver $UAUDVersion ===";Log 'TRUE BASELINE ver 1.0.0: future releases may only build upon this contract.';Log '[DIAGNOSTIC] UAUD is running its diagnostic phase.';$d=Diagnose
if($d.Problems.Count){Log ('[DIAGNOSTIC] '+$d.Problems.Count+' actionable issue(s) found.');$deployment=DeployUARD;if($deployment-eq'DEPLOYED'-or$deployment-eq'CURRENT'){Log '[UARD] Launching UARD in a dedicated visible PowerShell window.';$p=Start-Process powershell.exe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$RepairPath) -WorkingDirectory $Root -WindowStyle Normal -PassThru -ErrorAction SilentlyContinue;if($p){$p.WaitForExit();$repairResult=if($p.ExitCode-eq0){'SUCCESS'}elseif($p.ExitCode-eq2){'VERIFICATION UNKNOWN'}else{'FAILURE'};Log ('[UARD] Finished with exit code '+$p.ExitCode+' / '+$repairResult)}else{$repairResult='START FAILURE';Log '[UARD] Could not create the live PowerShell window.'}}else{$repairResult='NOT DEPLOYED';Log '[UARD] Not launched because deployment was not verified.'}}else{Log '[DIAGNOSTIC] No actionable issue: UARD deployment/launch not required.';$deployment='NOT NEEDED';$repairResult='NOT NEEDED'}
Log '[DIAGNOSTIC] Running final UAUD verification after UARD.';$f=Diagnose
if($repairResult-eq'SUCCESS'){$remaining=@($f.Problems|?{$_-notlike'Untrapped core differs from canonical GitHub:*'-and$_-notlike'Enhanced extension source differs from canonical GitHub:*'-and$_-notlike'Packet filter is not running.'-and$_-notlike'Control plane is not running.'})}else{$remaining=@($f.Problems)}
$overall=if($remaining.Count){'UNHEALTHY'}else{'HEALTHY'};$out=@('CONDENSED DIAGNOSIS',' OVERALL: '+$overall,' UAUD: '+$UAUDName+' ver '+$UAUDVersion,' UARD deployment: '+$deployment,' UARD result: '+$repairResult,' Remaining problems: '+$remaining.Count);foreach($x in$remaining){$out+=' ! '+$x};$out+=('');$out+=('DETAILED DIAGNOSIS');$out+=(' Policy and target state checked before and after UARD.');$out+=(' Core source: '+$(if($repairResult-eq'SUCCESS'){'REPAIRED + VERIFIED'}elseif($f.CoreBad.Count){'MISMATCH'}elseif($f.CoreUnknown.Count){'UNVERIFIED'}else{'CURRENT'}));$out+=(' Extension source: '+$(if($repairResult-eq'SUCCESS'){'REPAIRED + VERIFIED'}elseif($f.ExtBad.Count){'MISMATCH'}elseif($f.ExtUnknown.Count){'UNVERIFIED'}else{'CURRENT'}));$out+=(' Brave copies: '+$f.Brave.Count+' (0 = informational only)');$out+=(' Packet filter: '+$(if($f.Packet.Count){'RUNNING'}else{'STOPPED'}));$out+=(' Control plane: '+$(if($f.Control.Count){'RUNNING'}else{'STOPPED'}));$out+=(' DNS: '+$(if($f.Dns){'OK'}else{'FAILED'}));$out+=(' Google HTTPS: '+$(if($f.Google){'OK'}else{'FAILED'}));$out+=(' Hosts: '+$f.Hosts.Count);$out+=(' BFE: '+$(if($f.Bfe){'RUNNING'}else{'NOT RUNNING/UNKNOWN'}));$out+=('');$out+=('EXPLANATORY TABLE');$out+=('Component | Owner | Behaviour');$out+=('UAUD | Update + diagnosis | Checks system, policy and source; deploys UARD when needed');$out+=('UARD | Repair + verification | Repairs Untrapped-owned components, then exits');$out+=('Live PowerShell | UARD only | Visible while repair is running, closes when UARD exits');$out+=('Notepad | Both | UAUD always opens diagnostic-latest.txt; UARD opens repair-success-latest.txt when it repairs or fails');$out+=('Network/security infrastructure | UAUD diagnosis only | Never automatically modified');$out+=('');$out+=('VERSION / BASELINE');$out+=('UAUD: '+$UAUDVersion);$out+=('UARD: '+$UARDVersion);$out+=('TRUE BASELINE: 1.0.0');$out+=('');$out+=('DIAGNOSTIC CONTRACT');$out+=('UAUD owns update/diagnosis/orchestration; UARD owns repair.');$out+=('UARD is deployed and SHA-256 verified before launch.');$out+=('UARD runs in its own visible PowerShell window and exits when complete.');$out+=('Windows Firewall/WFP/DNS/routes/Hosts/proxy/adapters/VPN/override policy are never automatically modified.');$all=@($lines)+@('')+$out;try{$all|Set-Content $ReportPath -Encoding UTF8}catch{};Write-Host '';Write-Host ('================ '+$UAUDName+' ver '+$UAUDVersion+' ================');$out|%{Write-Host $_};Write-Host ('Report: '+$ReportPath);try{Start-Process notepad.exe -ArgumentList @($ReportPath) -ErrorAction Stop;Write-Host '[REPORT] diagnostic-latest.txt opened in Notepad.'}catch{Write-Host ('[REPORT] Notepad could not be opened: '+$_.Exception.Message)}